        first.add(scanner.nextInt());
        second.add(scanner.nextInt());
        System.out.println(first.value);
        System.out.println(second.value);
        // 공유 필드는 클래스 이름으로 읽어요.
        System.out.println(Counter.totalAdded);
    }
    // 인스턴스 필드는 객체마다 따로 보관해요.
    static class Counter {
        int value;
        // 모든 객체가 공유하는 누적값이에요.
        static int totalAdded = 0;
        // 반환형이 없는 생성자로 처음 값을 정해요.
        Counter(int initial) { value = initial; }
        // 이 객체의 값만 전달한 만큼 늘려요.
        void add(int amount) { value += amount; totalAdded += amount; }
    }
}

